SELECT ap.id, ap.acceptance_id, t.id AS task_id, t.title AS task_title, t.publisher_id, ap.appellant_id, ap.appeal_type, ap.reason, ap.evidence_images AS evidence_images_json, ap.status, ap.result, ap.handler_id, ap.handle_remark, ap.handled_at, ap.created_at, IF(ap.appeal_type = 1, t.publisher_id, a.acceptor_id) AS respondent_id FROM task_appeal ap INNER JOIN task_acceptance a ON ap.acceptance_id = a.id INNER JOIN task t ON a.task_id = t.id WHERE ap.deleted = 0
AND ap.status = #{query.status}
AND ap.appeal_type = #{query.appealType}
AND ap.created_at >= #{query.startDate}
AND ap.created_at < #{query.endDate}
ORDER BY ap.created_at DESC

SELECT COUNT(*)
FROM task_appeal ap
WHERE ap.deleted = 0

    AND ap.status = #{query.status}


    AND ap.appeal_type = #{query.appealType}


    AND ap.created_at >= #{query.startDate}


    AND ap.created_at < #{query.endDate}
